var root=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(EchoStation.InfiltrationArt.Editor.ArtSampleAssets.PathFor("Floor"));var f=root.GetComponentInChildren<UnityEngine.MeshFilter>();var m=f.sharedMesh;var v=m.vertices;var matrix=root.transform.worldToLocalMatrix*f.transform.localToWorldMatrix;var rows=new Newtonsoft.Json.Linq.JArray();double total=0;
for(int sub=0;sub<m.subMeshCount;sub++){var t=m.GetTriangles(sub);for(int i=0;i<t.Length;i+=3){var a=matrix.MultiplyPoint3x4(v[t[i]]);var b=matrix.MultiplyPoint3x4(v[t[i+1]]);var c=matrix.MultiplyPoint3x4(v[t[i+2]]);var area=UnityEngine.Vector3.Cross(b-a,c-a).magnitude*.5;total+=area;rows.Add(new Newtonsoft.Json.Linq.JObject{{"sub",sub},{"indices",new Newtonsoft.Json.Linq.JArray(t[i],t[i+1],t[i+2])},{"area",area},{"xyz",new Newtonsoft.Json.Linq.JArray(a.x,a.y,a.z,b.x,b.y,b.z,c.x,c.y,c.z)}});}}
return new {submeshes=m.subMeshCount,area=total,faces=rows};
